function evaluate(v,recognized,aligned){
 const ids=['u','v','h','z0','ex','ey','ez'];
 if(!recognized||!aligned)return {status:'待确认',message:'先确认真实关键边和测量基准方向，不能用罩顶、注水嘴或底排口代替。'};
 if(ids.some(k=>v[k]===''||v[k]===null||v[k]===undefined||!Number.isFinite(Number(v[k]))))return {status:'待测',message:'补齐全部读数及误差；空白不能按零。'};
 v=Object.fromEntries(ids.map(k=>[k,Number(v[k])]));if(['ex','ey','ez'].some(k=>v[k]<0))return {status:'输入错误',message:'误差须为非负数。'};
 const X=-955+v.u,Y=-135+v.v,Z=v.z0+v.h;
 let nominal=Infinity,lower=Infinity,upper=Infinity,worst='';
 for(const p of poses){const t=Math.tan(p.pitch_deg*Math.PI/180),s=Math.tan(p.roll_deg*Math.PI/180),n=Math.hypot(1,t,s);
 const H=(Z-p.reference_water_m*1000-t*(X+740)-s*(Y+130))/n;
 const E=(v.ez+Math.abs(t)*v.ex+Math.abs(s)*v.ey)/n;
 nominal=Math.min(nominal,H);upper=Math.min(upper,H+E);
 if(H-E<lower){lower=H-E;worst=p.case+'，横倾 '+p.roll_deg.toFixed(3)+'°';}}
 const status=lower>=600-1e-8?'模型预算满足':upper<600-1e-8?'模型预算不足':'误差范围跨越600mm';
 return {status,nominal,lower,upper,worst,X,Y,Z,message:'仅适用于本版静态停机水量与±5°回正工况；不是实机/动态验证。'};
}
if(typeof module!=='undefined')module.exports={evaluate,poses};
